/* gen.h - what the recompiled blocks (gen_all.c, generated by tools/p2rec.py) need. */
#ifndef P2_GEN_H
#define P2_GEN_H
#include "../core/cpu.h"
#include "../hal/hal.h"

#define GAME_CS ((uint16_t)(LOAD_SEG + 0x20u))
#define GAME_CODE_LIN ((uint32_t)GAME_CS * 16u)
#define REL(x) ((uint16_t)((x) + LOAD_SEG))

typedef int (*GenFn)(Cpu *c);      /* 1: ran (c->ip is the next block), 0: declined */
typedef struct GenBlock {
    uint16_t ip;
    GenFn fn;
} GenBlock;

extern const GenBlock g_gen_blocks[];
extern const unsigned g_gen_block_count;

void gen_install(int on);           /* the recompiled code runs in place of the interpreter */
extern uint64_t g_gen_blocks_run;

#endif
